-- DailyTest 2026-11-06: Pakistan Studies import (39 MCQs).
-- Generated from content files (validated + deduped). Idempotent.

insert into public.books (title) values ('Pakistan Studies') on conflict (title) do nothing;

insert into public.categories (book_id, name)
select id, 'Indus Valley Civilization' from public.books where title = 'Pakistan Studies'
on conflict (book_id, name) do nothing;

insert into public.mcqs (book_id, category_id, question_en, question_ur, options,
  correct_text, explanation, source_ref, difficulty, level, review_status)
select b.id, c.id, v.question_en, nullif(v.question_ur, ''), v.options::jsonb,
  v.correct_text, v.explanation, v.source_ref, v.difficulty, v.level, v.review_status
from public.books b join public.categories c on c.book_id = b.id
join (values
  ('Indus Valley Civilization', 'The Indus Valley Civilization is also known as?', 'وادی سندھ کی تہذیب کو اور کس نام سے جانا جاتا ہے؟', '{"A": "Egyptian Civilization", "B": "Mesopotamian Civilization", "C": "Chinese Civilization", "D": "Harappan Civilization"}', 'Harappan Civilization', 'Named after Harappa, the first site excavated in Punjab.', 'pak-studies-001', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'Which was the largest city of the Indus Valley Civilization?', 'وادی سندھ کی تہذیب کا سب سے بڑا شہر کون سا تھا؟', '{"A": "Lothal", "B": "Kalibangan", "C": "Mohenjo-Daro", "D": "Harappa"}', 'Mohenjo-Daro', 'Mohenjo-Daro in Sindh was the largest settlement, covering about 200 hectares.', 'pak-studies-002', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'The Great Bath was discovered at which site?', 'عظیم حمام کس مقام پر دریافت ہوا؟', '{"A": "Mohenjo-Daro", "B": "Rakhigarhi", "C": "Dholavira", "D": "Harappa"}', 'Mohenjo-Daro', 'The watertight Great Bath is the most famous structure at Mohenjo-Daro.', 'pak-studies-003', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'Which metal was unknown to the Indus Valley people?', 'وادی سندھ کے لوگوں کو کون سی دھات معلوم نہیں تھی؟', '{"A": "Silver", "B": "Iron", "C": "Gold", "D": "Copper"}', 'Iron', 'The Harappans used copper, bronze, gold and silver; iron reached India later.', 'pak-studies-004', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'The script of Indus Valley Civilization is?', 'وادی سندھ کی تہذیب کی رسم الخط کیا ہے؟', '{"A": "Undeciphered", "B": "Pictographic only", "C": "Alphabetical", "D": "Deciphered"}', 'Undeciphered', 'The Harappan script has never been deciphered, so much about them stays unknown.', 'pak-studies-005', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'Harappa is located on the bank of which river?', 'ہڑپہ کس دریا کے کنارے واقع ہے؟', '{"A": "Ravi", "B": "Chenab", "C": "Jhelum", "D": "Indus"}', 'Ravi', 'Harappa stands near the Ravi river in Sahiwal district, Punjab.', 'pak-studies-006', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'Mohenjo-Daro means?', 'موہن جو دڑو کا مطلب کیا ہے؟', '{"A": "Great Fort", "B": "City of Gods", "C": "Mound of the Dead", "D": "Market Place"}', 'Mound of the Dead', 'The Sindhi name Mohenjo-Daro means Mound of the Dead.', 'pak-studies-007', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'The Indus Valley Civilization belonged to which age?', 'وادی سندھ کی تہذیب کس دور سے تعلق رکھتی ہے؟', '{"A": "Iron Age", "B": "Copper Age only", "C": "Bronze Age", "D": "Stone Age"}', 'Bronze Age', 'Copper and bronze tools place it in the Bronze Age, about 2600 to 1900 BCE.', 'pak-studies-008', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'Lothal was a famous port of?', 'لوتھل کس تہذیب کا مشہور بندرگاہ تھا؟', '{"A": "Indus Valley", "B": "Mauryan", "C": "Vedic", "D": "Gupta"}', 'Indus Valley', 'Lothal in Gujarat had a dockyard and traded by sea.', 'pak-studies-009', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'Who discovered Harappa?', 'ہڑپہ کی دریافت کس نے کی؟', '{"A": "John Marshall", "B": "Alexander Cunningham", "C": "Dayaram Sahni", "D": "R.D. Banerjee"}', 'Dayaram Sahni', 'Dayaram Sahni excavated Harappa in 1921 under John Marshall.', 'pak-studies-010', 'hard', 'advanced', 'ai_verified'),
  ('Indus Valley Civilization', 'Mohenjo-Daro was discovered by?', 'موہن جو دڑو کی دریافت کس نے کی؟', '{"A": "Mortimer Wheeler", "B": "Dayaram Sahni", "C": "John Marshall", "D": "R.D. Banerjee"}', 'R.D. Banerjee', 'R. D. Banerjee found Mohenjo-Daro in 1922.', 'pak-studies-011', 'hard', 'advanced', 'ai_verified'),
  ('Indus Valley Civilization', 'The famous dancing girl statue is made of?', 'مشہور رقاصہ کا مجسمہ کس چیز سے بنا ہے؟', '{"A": "Gold", "B": "Terracotta", "C": "Stone", "D": "Bronze"}', 'Bronze', 'The small dancing-girl statue from Mohenjo-Daro is cast in bronze.', 'pak-studies-012', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'Which tree was sacred in Indus Valley?', 'وادی سندھ میں کون سا درخت مقدس تھا؟', '{"A": "Mango", "B": "Neem", "C": "Peepal", "D": "Banyan"}', 'Peepal', 'The peepal (sacred fig) appears on seals and was worshipped.', 'pak-studies-013', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'The Indus Valley Civilization extended to?', 'وادی سندھ کی تہذیب کہاں تک پھیلی ہوئی تھی؟', '{"A": "Only Sindh", "B": "Bengal", "C": "Only Punjab", "D": "Present day Pakistan and NW India"}', 'Present day Pakistan and NW India', 'At its peak it covered present-day Pakistan and northwestern India.', 'pak-studies-014', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'Which god was worshipped in Indus Valley resembling Shiva?', 'وادی سندھ میں شیو سے مشابہ کون سا دیوتا پوجا جاتا تھا؟', '{"A": "Pashupati", "B": "Indra", "C": "Agni", "D": "Varuna"}', 'Pashupati', 'A seal shows a horned figure among animals, linked to Pashupati, an early Shiva.', 'pak-studies-015', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'Decline of Indus Valley is attributed to?', 'وادی سندھ کی تہذیب کے زوال کی وجہ کیا بتائی جاتی ہے؟', '{"A": "Volcanic eruption", "B": "Floods, climate change, Aryan invasion theories", "C": "Only wars", "D": "Only earthquakes"}', 'Floods, climate change, Aryan invasion theories', 'No single cause is proven; floods, river shifts, climate change and invasions are all suggested.', 'pak-studies-016', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'Cotton was first grown in?', 'کپاس سب سے پہلے کہاں اگائی گئی؟', '{"A": "Egypt", "B": "Mesopotamia", "C": "China", "D": "Indus Valley"}', 'Indus Valley', 'The earliest cotton threads and cloth come from Indus sites.', 'pak-studies-017', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'The seals of Indus Valley were mostly made of?', 'وادی سندھ کی مہریں زیادہ تر کس چیز کی بنی ہوتی تھیں؟', '{"A": "Gold", "B": "Wood", "C": "Steatite", "D": "Iron"}', 'Steatite', 'Most seals were cut from steatite (soapstone) and glazed white.', 'pak-studies-018', 'hard', 'advanced', 'ai_verified'),
  ('Indus Valley Civilization', 'Which site has a dockyard?', 'کس مقام پر گودی (ڈاک یارڈ) ہے؟', '{"A": "Banawali", "B": "Mohenjo-Daro", "C": "Harappa", "D": "Lothal"}', 'Lothal', 'Lothal brick dockyard is the earliest known in the world.', 'pak-studies-019', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'The Indus people traded with?', 'وادی سندھ کے لوگ کس کے ساتھ تجارت کرتے تھے؟', '{"A": "Mesopotamia", "B": "Rome", "C": "Greece", "D": "America"}', 'Mesopotamia', 'Mesopotamian texts call the Indus region Meluha and record trade with it.', 'pak-studies-020', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'Bead making factory was found at?', 'موتی بنانے کی فیکٹری کہاں ملی؟', '{"A": "Chanhudaro", "B": "Mohenjo-Daro", "C": "Kalibangan", "D": "Harappa"}', 'Chanhudaro', 'Chanhudaro in Sindh had bead-making workshops but no citadel.', 'pak-studies-021', 'hard', 'advanced', 'ai_verified'),
  ('Indus Valley Civilization', 'The streets of Indus cities were?', 'وادی سندھ کے شہروں کی سڑکیں کیسی تھیں؟', '{"A": "Grid pattern, right angles", "B": "Narrow only", "C": "Irregular", "D": "Circular"}', 'Grid pattern, right angles', 'Streets were laid out in a grid at right angles.', 'pak-studies-022', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'IVC was a?', 'وادی سندھ کی تہذیب کیا تھی؟', '{"A": "Rural only", "B": "Tribal", "C": "Nomadic", "D": "Urban civilization"}', 'Urban civilization', 'Planned cities with drains and granaries make it an urban civilization.', 'pak-studies-023', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'Which river is associated with IVC mainly?', 'وادی سندھ کی تہذیب بنیادی طور پر کس دریا سے وابستہ ہے؟', '{"A": "Yamuna", "B": "Brahmaputra", "C": "Indus and its tributaries", "D": "Ganga"}', 'Indus and its tributaries', 'Its settlements cluster along the Indus river system.', 'pak-studies-024', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'The citadel in IVC cities was used for?', 'وادی سندھ کے شہروں میں قلعہ نما حصہ کس لیے استعمال ہوتا تھا؟', '{"A": "Markets only", "B": "Public buildings, granaries, baths", "C": "Only residences", "D": "Farms"}', 'Public buildings, granaries, baths', 'The raised citadel held the granary, baths and public halls.', 'pak-studies-025', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'Dholavira is famous for?', 'دھولاویرا کس چیز کے لیے مشہور ہے؟', '{"A": "Great Bath", "B": "Dancing girl", "C": "Water management and reservoirs", "D": "Dockyard"}', 'Water management and reservoirs', 'Dholavira in Kutch is noted for its reservoirs and water harvesting.', 'pak-studies-026', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'The standard weight in IVC was?', 'وادی سندھ میں معیاری وزن کیا تھا؟', '{"A": "20", "B": "12", "C": "10 only", "D": "16 ratio system"}', '16 ratio system', 'Weights followed a 16-based ratio that survived in South Asia for centuries.', 'pak-studies-027', 'hard', 'advanced', 'ai_verified'),
  ('Indus Valley Civilization', 'Which crop was known to IVC?', 'وادی سندھ کو کون سی فصل معلوم تھی؟', '{"A": "Only rice", "B": "Potato", "C": "Wheat, barley, cotton, peas", "D": "Maize"}', 'Wheat, barley, cotton, peas', 'They grew wheat, barley, peas and cotton; potato and maize came from America much later.', 'pak-studies-028', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'The IVC had knowledge of?', 'وادی سندھ کو کس چیز کا علم تھا؟', '{"A": "Gunpowder", "B": "Only pottery", "C": "Drainage system, town planning", "D": "Iron tools"}', 'Drainage system, town planning', 'Covered drains and grid streets show their town planning; they had no iron or gunpowder.', 'pak-studies-029', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'Banawali is located in?', 'بناولی کہاں واقع ہے؟', '{"A": "Haryana", "B": "Punjab Pakistan", "C": "Sindh", "D": "Balochistan"}', 'Haryana', 'Banawali is a Harappan site in Haryana, India.', 'pak-studies-030', 'hard', 'advanced', 'ai_verified'),
  ('Indus Valley Civilization', 'The period of mature Harappan phase is?', 'پختہ ہڑپہ دور کا عرصہ کیا ہے؟', '{"A": "3000-2500 BCE", "B": "2600-1900 BCE", "C": "1000-500 BCE", "D": "1500-1000 BCE"}', '2600-1900 BCE', 'The mature urban phase ran about 2600 to 1900 BCE.', 'pak-studies-031', 'hard', 'advanced', 'ai_verified'),
  ('Indus Valley Civilization', 'Which animal is most depicted on seals?', 'مہروں پر سب سے زیادہ کون سا جانور دکھایا گیا ہے؟', '{"A": "Unicorn / Bull", "B": "Horse", "C": "Elephant", "D": "Tiger"}', 'Unicorn / Bull', 'The one-horned unicorn is the commonest animal on the seals.', 'pak-studies-032', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'The IVC script has how many signs approximately?', 'وادی سندھ کی رسم الخط میں تقریباً کتنے علامات ہیں؟', '{"A": "400-600", "B": "50", "C": "1000", "D": "26"}', '400-600', 'About 400 to 600 distinct script signs are known.', 'pak-studies-033', 'hard', 'advanced', 'ai_verified'),
  ('Indus Valley Civilization', 'Alamgirpur is the easternmost site of IVC in?', 'عالمگیرپور وادی سندھ کا مشرقی ترین مقام ہے؟', '{"A": "Punjab", "B": "Gujarat", "C": "Uttar Pradesh", "D": "Sindh"}', 'Uttar Pradesh', 'Alamgirpur in Uttar Pradesh marks the eastern limit of the civilization.', 'pak-studies-034', 'hard', 'advanced', 'ai_verified'),
  ('Indus Valley Civilization', 'The famous priest-king statue is from?', 'مشہور پجاری بادشاہ کا مجسمہ کہاں سے ہے؟', '{"A": "Harappa", "B": "Lothal", "C": "Mohenjo-Daro", "D": "Dholavira"}', 'Mohenjo-Daro', 'The bearded priest-king bust comes from Mohenjo-Daro.', 'pak-studies-035', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'IVC houses were made of?', 'وادی سندھ کے گھروں کی تعمیر کس سے ہوئی تھی؟', '{"A": "Mud only", "B": "Stone only", "C": "Wood", "D": "Baked bricks"}', 'Baked bricks', 'Standard-size baked bricks were used for houses and drains.', 'pak-studies-036', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'Which feature is unique to IVC town planning?', 'وادی سندھ کی شہر منصوبہ بندی کی منفرد خصوصیت کیا ہے؟', '{"A": "Pyramids", "B": "Covered drains and wells", "C": "Ziggurats", "D": "Colosseum"}', 'Covered drains and wells', 'No other Bronze Age culture had such covered drains and wells.', 'pak-studies-037', 'easy', 'basic', 'ai_verified'),
  ('Indus Valley Civilization', 'The term ''Meluha'' in Mesopotamian texts refers to?', 'میسوپوٹیمیائی متون میں ''میلوہا'' سے مراد کیا ہے؟', '{"A": "Indus Valley", "B": "China", "C": "Egypt", "D": "Greece"}', 'Indus Valley', 'Mesopotamian tablets call the Indus region Meluha.', 'pak-studies-038', 'medium', 'intermediate', 'ai_verified'),
  ('Indus Valley Civilization', 'The IVC ended around?', 'وادی سندھ کی تہذیب کا خاتمہ تقریباً کب ہوا؟', '{"A": "500 BCE", "B": "1900-1300 BCE", "C": "3000 BCE", "D": "1000 CE"}', '1900-1300 BCE', 'Cities declined after about 1900 BCE; the late phase lasted to around 1300 BCE.', 'pak-studies-039', 'medium', 'intermediate', 'ai_verified')
) as v(chapter, question_en, question_ur, options, correct_text, explanation,
  source_ref, difficulty, level, review_status) on c.name = v.chapter
where b.title = 'Pakistan Studies'
on conflict (content_hash) do nothing;

